#!/bin/bash
# Verifier entrypoint of a coding task. Generated by step1-build-tasks/coding_tasks.py; do not edit by hand.
#
#   test.sh                      Harbor's own verifier, in the agent's container: restore the test
#                                side, run the hidden tests, write /logs/verifier/reward.txt. The
#                                reward starts at 0, so a missing python3 or grader fails the task.
#   test.sh --stage untrusted    this module's staged grader (harbor_env/agentcore_env.py), as the agent user:
#                                run the tests on a copy of the repository and write the JUnit
#                                report and run.json to $OUT. No reward: this stage writes evidence.
#   test.sh --stage trusted      the staged grader, as the grader user, after the agent's processes
#                                are gone: read $IN's JUnit report and this folder's expected.json,
#                                write $OUT/reward.json. It runs a root-owned python3 in isolated
#                                mode, from here, and reads nothing from the repository.
# IN and OUT default to /logs/verifier, as the staged grader's contract has it.
set -u
MODE=all
[ "${1:-}" = --stage ] && MODE=${2:-}
case "$MODE" in all|untrusted|trusted) ;; *) echo "usage: test.sh [--stage untrusted|trusted]" >&2; exit 2 ;; esac
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
APP="${TASK_APP:-/work/repo}"

if [ "$MODE" = all ]; then
  LOGS="${TASK_LOGS:-/logs/verifier}"
  mkdir -p "$LOGS"
  echo 0 > "$LOGS/reward.txt"
  python3 "$HERE/grader.py" --tests "$HERE" --app "$APP" --logs "$LOGS"
  exit 0
fi

L="${OUT:-/logs/verifier}"
mkdir -p "$L"
if [ "$MODE" = untrusted ]; then
  python3 "$HERE/grader.py" --stage untrusted --tests "$HERE" --app "$APP" --out "$L"
  exit 0
fi

# trusted: nothing from the agent's reach. PATH is reset, and python3 must be a root-owned file
# that no one else can write, outside every folder the agent could write to.
export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
PY=
for candidate in /usr/bin/python3 /usr/local/bin/python3; do
  real=$(readlink -f "$candidate" 2>/dev/null) || continue
  case "$real" in /app/*|/work/*|/home/*|/tmp/*|/var/tmp/*|/run/*|/logs/*|/installed-agent/*|"$APP"/*) continue ;; esac
  [ -f "$real" ] && [ -x "$real" ] || continue
  set -- $(ls -ldn "$real")  # mode, links, uid, ...: owned by uid 0, not writable by group or others
  [ "$3" = 0 ] && [ "${1:5:1}" != w ] && [ "${1:8:1}" != w ] || continue
  PY=$real
  break
done
if [ -z "$PY" ]; then
  echo "task grader: no root-owned python3 outside the agent's reach for the trusted stage; not grading" >&2
  exit 3
fi
cd "$HERE" || exit 3
exec "$PY" -I -S "$HERE/grader.py" --stage trusted --tests "$HERE" --in "${IN:-/logs/verifier}" --out "$L"
